### 3.3 Embedded Signup Flow (iframe)

WhatsApp uses Meta's Embedded Signup via an iframe. The flow is handled in `IntegrateChannelSignup.js`:

**Step 1 — Trigger:**
```js
// User clicks "Connect with WhatsApp" button
iframeEle.contentWindow.postMessage(
  JSON.stringify({ type: EMBEDDED_SIGNUP_TRIGGER }),
  '*'
);
setState({ integBtnStatus: 'loading' });
```

**Step 2 — Listen for iframe response:**
```js
window.addEventListener('message', receiveMessage);

receiveMessage = (e) => {
  const parsedData = JSON.parse(e.data);

  if (parsedData.type === EMBEDDED_SIGNUP_SUCCESS) {
    updateWhatsAppAccount(parsedData.data);   // stores WABA + phone data
    integrationSuccessCallback(parsedData.data);
    setState({ integBtnStatus: 'none' });

  } else if (parsedData.type === EMBEDDED_SIGNUP_FAILURE) {
    integrationFailureCallback({ ...parsedData.data, isBSPMigration });
    setState({ integBtnStatus: 'none' });
  }
};
```

